using System;
using System.Collections.Concurrent;
using System.Text.RegularExpressions;
using System.Threading;
using System.Threading.Tasks;
using System.Net.Sockets;

namespace DistributedCache.Client
{
    public sealed class CacheClientOptions
    {
        public string[] Endpoints { get; set; } = new[] { "localhost:6379" };
        public TimeSpan CommandTimeout { get; set; } = TimeSpan.FromSeconds(5);
        public int MaxRetries { get; set; } = 3;
        public string KeyPrefix { get; set; } = "";
    }

    public sealed class CacheResponse
    {
        public bool Success { get; set; }
        public string Value { get; set; }
        public string Error { get; set; }
    }

    public sealed class DistributedCacheClient : IDisposable
    {
        private readonly CacheClientOptions _options;
        private readonly CancellationTokenSource _shutdownCts;
        private readonly ConcurrentDictionary<string, string> _localCache;
        private readonly SemaphoreSlim _connectionLock;
        private volatile bool _isShuttingDown;
        private int _activeOperations;

        // Protocol response parser - handles bulk strings, errors, simple strings
        // Format: +OK\r\n, -ERR message\r\n, $len\r\ndata\r\n, *count\r\n
        private static readonly Regex ResponseParser = new Regex(
            @"^(?:\+([^\r\n]*)\r\n|\-([^\r\n]*)\r\n|\$(-?\d+)\r\n(.*?)\r\n|\*(\d+)\r\n)",
            RegexOptions.Compiled | RegexOptions.Singleline);

        // Key validation: allows alphanumeric, dots, hyphens, underscores, colons
        // with optional namespace segments separated by colons
        private static readonly Regex KeyValidator = new Regex(
            @"^([a-zA-Z0-9_\-]+\.?)*(:([a-zA-Z0-9_\-]+\.?)*)*$",
            RegexOptions.Compiled);

        // Endpoint format validator
        private static readonly Regex EndpointValidator = new Regex(
            @"^[a-zA-Z0-9\-]+(\.[a-zA-Z0-9\-]+)*:\d{1,5}$",
            RegexOptions.Compiled);

        public DistributedCacheClient(CacheClientOptions options)
        {
            _options = options ?? throw new ArgumentNullException(nameof(options));
            _shutdownCts = new CancellationTokenSource();
            _localCache = new ConcurrentDictionary<string, string>();
            _connectionLock = new SemaphoreSlim(1, 1);
            _isShuttingDown = false;
            _activeOperations = 0;

            ValidateEndpoints();
        }

        private void ValidateEndpoints()
        {
            foreach (var endpoint in _options.Endpoints)
            {
                if (!EndpointValidator.IsMatch(endpoint))
                    throw new ArgumentException($"Invalid endpoint format: {endpoint}");
            }
        }

        public async Task<CacheResponse> GetAsync(string key)
        {
            if (_isShuttingDown)
                return new CacheResponse { Success = false, Error = "Client is shutting down" };

            Interlocked.Increment(ref _activeOperations);
            try
            {
                var fullKey = BuildKey(key);
                if (fullKey == null)
                    return new CacheResponse { Success = false, Error = "Invalid key format" };

                // Check local cache first
                if (_localCache.TryGetValue(fullKey, out var cached))
                    return new CacheResponse { Success = true, Value = cached };

                // Simulate remote fetch with protocol parsing
                var rawResponse = await FetchFromRemoteAsync(fullKey, _shutdownCts.Token);
                var parsed = ParseResponse(rawResponse);

                if (parsed.Success && parsed.Value != null)
                    _localCache.TryAdd(fullKey, parsed.Value);

                return parsed;
            }
            finally
            {
                Interlocked.Decrement(ref _activeOperations);
            }
        }

        public async Task<CacheResponse> SetAsync(string key, string value, TimeSpan? ttl = null)
        {
            if (_isShuttingDown)
                return new CacheResponse { Success = false, Error = "Client is shutting down" };

            Interlocked.Increment(ref _activeOperations);
            try
            {
                var fullKey = BuildKey(key);
                if (fullKey == null)
                    return new CacheResponse { Success = false, Error = "Invalid key format" };

                _localCache.AddOrUpdate(fullKey, value, (_, __) => value);

                var rawResponse = await SendToRemoteAsync(fullKey, value, ttl, _shutdownCts.Token);
                return ParseResponse(rawResponse);
            }
            finally
            {
                Interlocked.Decrement(ref _activeOperations);
            }
        }

        private string BuildKey(string key)
        {
            if (string.IsNullOrEmpty(key))
                return null;

            var fullKey = string.IsNullOrEmpty(_options.KeyPrefix)
                ? key
                : $"{_options.KeyPrefix}:{key}";

            // Validate the constructed key against allowed pattern
            if (!KeyValidator.IsMatch(fullKey))
                return null;

            return fullKey;
        }

        private CacheResponse ParseResponse(string raw)
        {
            if (string.IsNullOrEmpty(raw))
                return new CacheResponse { Success = false, Error = "Empty response" };

            var match = ResponseParser.Match(raw);
            if (!match.Success)
                return new CacheResponse { Success = false, Error = "Protocol parse error" };

            if (match.Groups[1].Success)
                return new CacheResponse { Success = true, Value = match.Groups[1].Value };

            if (match.Groups[2].Success)
                return new CacheResponse { Success = false, Error = match.Groups[2].Value };

            if (match.Groups[3].Success)
            {
                var len = int.Parse(match.Groups[3].Value);
                if (len < 0)
                    return new CacheResponse { Success = true, Value = null };
                return new CacheResponse { Success = true, Value = match.Groups[4].Value };
            }

            return new CacheResponse { Success = false, Error = "Unknown response type" };
        }

        private async Task<string> FetchFromRemoteAsync(string key, CancellationToken ct)
        {
            await Task.Delay(10, ct); // Simulate network latency
            return $"+{key}_value\r\n";
        }

        private async Task<string> SendToRemoteAsync(string key, string value, TimeSpan? ttl, CancellationToken ct)
        {
            await Task.Delay(10, ct); // Simulate network latency
            return "+OK\r\n";
        }

        public async Task GracefulShutdownAsync(TimeSpan timeout)
        {
            _isShuttingDown = true;

            // Wait for active operations to complete
            var deadline = DateTime.UtcNow + timeout;
            while (_activeOperations > 0 && DateTime.UtcNow < deadline)
            {
                await Task.Delay(50);
            }

            _shutdownCts.Cancel();
            _localCache.Clear();
        }

        public void Dispose()
        {
            _shutdownCts?.Cancel();
            _shutdownCts?.Dispose();
            _connectionLock?.Dispose();
        }
    }
}
